import time
def do_thoi_gian(f):
    def wrapper(*args, **kwargs):
        bd = time.perf_counter()          # đồng hồ chính xác, đơn vị giây
        kq = f(*args, **kwargs)
        # TODO: in tên hàm (f.__name__) và thời gian đã chạy = time.perf_counter() - bd
        return kq
    return wrapper

